import React, { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'at-risk' | 'over' | 'done';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  active: { label: 'В норме', tone: 'success' },
  'at-risk': { label: 'На грани', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  done: { label: 'Завершён', tone: 'info' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Ребрендинг сайта', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Мобильное приложение', quotaPercent: 88, status: 'at-risk' },
  { id: 'p3', name: 'Миграция на новый CRM', quotaPercent: 112, status: 'over' },
  { id: 'p4', name: 'Аналитика продаж Q3', quotaPercent: 100, status: 'done' },
  { id: 'p5', name: 'Оптимизация склада', quotaPercent: 35, status: 'active' },
  { id: 'p6', name: 'Партнёрская интеграция', quotaPercent: 95, status: 'at-risk' },
  { id: 'p7', name: 'Внутренний портал', quotaPercent: 60, status: 'active' },
  { id: 'p8', name: 'Юридический аудит', quotaPercent: 120, status: 'over' },
  { id: 'p9', name: 'Обновление документации', quotaPercent: 100, status: 'done' },
  { id: 'p10', name: 'Каталог поставщиков', quotaPercent: 20, status: 'active' },
  { id: 'p11', name: 'Локализация продукта', quotaPercent: 78, status: 'at-risk' },
  { id: 'p12', name: 'Пилот по автоматизации', quotaPercent: 105, status: 'over' },
];

const PAGE_SIZE = 5;
const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

export default function ProjectQuotaPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses([]);
    setPage(1);
  };

  const filtered = useMemo(() => {
    if (selectedStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((project) => selectedStatuses.includes(project.status));
  }, [selectedStatuses]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div
      className="jx-surface"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '24px',
        borderRadius: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        maxWidth: '640px',
      }}
    >
      <div>
        <h2
          style={{
            margin: 0,
            marginBottom: '4px',
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            fontSize: '20px',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты по каждому проекту
        </p>
      </div>

      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {ALL_STATUSES.map((status) => {
          const isActive = selectedStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => removeStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные статусы фильтра проектов нет."
          action={<JxButton variant="primary" onClick={resetFilters}>Сбросить фильтры</JxButton>}
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px 16px',
                  borderRadius: 'var(--jx-r)',
                  border: '1px solid var(--jx-border)',
                  background: 'var(--jx-surface-2)',
                }}
              >
                <span
                  style={{
                    color: 'var(--jx-text)',
                    fontSize: '15px',
                    fontWeight: 500,
                    flex: 1,
                    minWidth: 0,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {project.name}
                </span>

                <JxProgressCircle value={project.quotaPercent} showValue />

                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

